//! Shapes of the bundled tables generated by `build.rs` (see its module doc for
//! the merged layout). Everything here is `'static` data; `Dict` views resolve a
//! version's exact values through the presence masks and overrides.

use super::model::Datatype;

/// Bit `i` = the bundled version whose `StaticDict::mask_bit` is `i` (the
/// ordinal `build.rs` assigns, in `BUNDLED_VERSIONS` order).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct VersionMask(pub u16);

impl VersionMask {
    /// How many bundled versions a mask can address; `build.rs` asserts against it.
    pub const BITS: usize = 16;

    /// The only place that interprets the mask; `mask_bit` values are ordinals.
    pub const fn contains(self, ordinal: u8) -> bool {
        self.0 & (1 << ordinal) != 0
    }
}

/// One tag across all bundled versions. Base values are the latest version's;
/// an override row records what the versions in its mask see instead.
#[derive(Debug)]
pub struct TagRecord {
    pub tag: u32,
    pub name: &'static str,
    pub datatype: &'static str,
    pub datatype_class: Datatype,
    pub description: &'static str,
    pub added: &'static str,
    pub deprecated: &'static str,
    /// The extension pack recorded against `added`, or 0 when none is. No
    /// override bucket: every version is enriched from one metadata file, so
    /// this cannot differ between them, and `build.rs` asserts it.
    pub added_ep: u16,
    pub presence: VersionMask,
    pub overrides: &'static [FieldOverride],
    /// Sorted by `value`; each carries its own presence mask.
    pub enums: &'static [EnumRecord],
}

#[derive(Debug)]
pub struct FieldOverride {
    pub versions: VersionMask,
    pub name: Option<&'static str>,
    pub datatype: Option<&'static str>,
    pub datatype_class: Option<Datatype>,
    pub description: Option<&'static str>,
    pub added: Option<&'static str>,
    pub deprecated: Option<&'static str>,
}

#[derive(Debug)]
pub struct EnumRecord {
    pub value: &'static str,
    pub name: &'static str,
    pub description: &'static str,
    pub added: &'static str,
    /// As `TagRecord::added_ep`.
    pub added_ep: u16,
    pub presence: VersionMask,
    pub overrides: &'static [EnumOverride],
}

#[derive(Debug)]
pub struct EnumOverride {
    pub versions: VersionMask,
    pub name: Option<&'static str>,
    pub description: Option<&'static str>,
    pub added: Option<&'static str>,
}

#[derive(Debug)]
pub struct StaticGroup {
    pub name: &'static str,
    pub count_tag: u32,
    pub delimiter_tag: u32,
    pub members: &'static [u32],
    pub nested: &'static [u16],
}

#[derive(Debug)]
pub struct StaticMessage {
    pub msg_type: &'static str,
    pub name: &'static str,
    pub category: &'static str,
    pub description: &'static str,
    pub groups: &'static [u16],
}

/// One bundled version: its mask bit into `TAGS` plus its own groups/messages.
#[derive(Debug)]
pub struct StaticDict {
    pub version: &'static str,
    pub mask_bit: u8,
    /// Sorted session-layer tags, for `Dict::is_header`/`is_trailer`.
    pub header: &'static [u32],
    pub trailer: &'static [u32],
    pub groups: &'static [StaticGroup],
    pub messages: &'static [StaticMessage],
}

impl TagRecord {
    pub fn override_for(&self, bit: u8) -> Option<&'static FieldOverride> {
        self.overrides.iter().find(|o| o.versions.contains(bit))
    }
}

impl EnumRecord {
    pub fn override_for(&self, bit: u8) -> Option<&'static EnumOverride> {
        self.overrides.iter().find(|o| o.versions.contains(bit))
    }
}

include!(concat!(env!("OUT_DIR"), "/dicts.rs"));
